<?php require_once __DIR__.'/../includes/admin-auth.php';require_admin(['super_admin','event_admin']);$pageTitle='Registrations';$q=trim($_GET['q']??'');$event=(int)($_GET['event_id']??0);$att=$_GET['attendance']??'';$events=$pdo->query('SELECT id,title FROM events ORDER BY event_date DESC')->fetchAll();$sql="SELECT r.*,u.name,u.email,e.title event_title,e.event_date,c.checked_in_at FROM registrations r JOIN users u ON u.id=r.user_id JOIN events e ON e.id=r.event_id LEFT JOIN checkins c ON c.registration_id=r.id WHERE (u.name LIKE ? OR u.email LIKE ? OR r.registration_code LIKE ? OR r.entry_code LIKE ?)";$params=["%$q%","%$q%","%$q%","%$q%"] ;if($event){$sql.=' AND e.id=?';$params[]=$event;}if($att==='checked')$sql.=' AND c.id IS NOT NULL';elseif($att==='unchecked')$sql.=' AND c.id IS NULL';$sql.=' ORDER BY r.created_at DESC LIMIT 500';$s=$pdo->prepare($sql);$s->execute($params);$regs=$s->fetchAll();if(isset($_GET['export'])&&$_GET['export']==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="campuspass-registrations.csv"');$out=fopen('php://output','w');fputcsv($out,['Registration ID','Participant','Email','Event','Event date','Status','Checked in']);foreach($regs as $r)fputcsv($out,[$r['registration_code'],$r['name'],$r['email'],$r['event_title'],$r['event_date'],$r['status'],$r['checked_in_at']?'Yes':'No']);fclose($out);exit;}require __DIR__.'/../includes/admin-layout.php'; ?><div class="panel"><form class="row g-2 mb-3" data-validate novalidate data-no-lock><div class="col-md-5"><input class="form-control" maxlength="80" name="q" value="<?=e($q)?>" placeholder="Name, email, registration ID, entry code"></div><div class="col-md-3"><select class="form-select" name="event_id"><option value="0">All events</option><?php foreach($events as $ev): ?><option value="<?=$ev['id']?>" <?=$event===$ev['id']?'selected':''?>><?=e($ev['title'])?></option><?php endforeach; ?></select></div><div class="col-md-2"><select class="form-select" name="attendance"><option value="">All attendance</option><option value="checked" <?=$att==='checked'?'selected':''?>>Checked in</option><option value="unchecked" <?=$att==='unchecked'?'selected':''?>>Not checked in</option></select></div><div class="col-md-2 d-grid"><button class="btn btn-primary">Filter</button></div></form><div class="d-flex justify-content-between mb-3"><span class="muted small"><?=count($regs)?> matching registrations (max 500)</span><a class="btn btn-sm btn-outline-primary" href="?<?=http_build_query(['q'=>$q,'event_id'=>$event,'attendance'=>$att,'export'=>'csv'])?>">Export CSV</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Participant</th><th>Event</th><th>Registration ID</th><th>Registered</th><th>Attendance</th><th>Status</th></tr></thead><tbody><?php foreach($regs as $r): ?><tr><td><strong><?=e($r['name'])?></strong><div class="small muted"><?=e($r['email'])?></div></td><td><?=e($r['event_title'])?><div class="small muted"><?=e(date('M j, Y',strtotime($r['event_date'])))?></div></td><td><?=e($r['registration_code'])?></td><td><?=e(date('M j, Y',strtotime($r['created_at'])))?></td><td><span class="status-pill <?=$r['checked_in_at']?'status-checked':'status-pending'?>"><?=$r['checked_in_at']?'Checked in':'Not checked in'?></span></td><td><?=e($r['status'])?></td></tr><?php endforeach; ?></tbody></table></div></div><?php require __DIR__.'/../includes/admin-footer.php'; ?>
